import {mkdirSync,readFileSync,writeFileSync,symlinkSync,mkdtempSync} from 'node:fs';
import {join,resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {instrumentTypeScriptWithCoverage} from '../scripts/run-istanbul-bun-coverage';
import {sourceHash} from '../scripts/quality-inventory';
const root=process.cwd();
const work=mkdtempSync(join(root,'.git','b11-driver-measure-'));
const helperPaths=['tests/helpers/test-database.ts','tests/helpers/owned-test-directory.ts','tests/helpers/test-database.test.ts'];
mkdirSync(join(work,'tests','helpers'),{recursive:true});
symlinkSync(join(root,'src'),join(work,'src'),process.platform==='win32'?'junction':'dir');
for(const path of helperPaths){
 const source=readFileSync(path,'utf8');
 const built=instrumentTypeScriptWithCoverage(source,resolve(path));
 writeFileSync(join(work,path),built.code);
}

writeFileSync(join(work,'capture.ts'),'import {afterAll} from "bun:test";\nimport {writeFileSync} from "node:fs";\nafterAll(()=>writeFileSync("coverage.json",JSON.stringify((globalThis as any).__coverage__)));\n');
writeFileSync(join(work,'bunfig.toml'),'[test]\ncoverage = false\ntimeout = 30000\npreload = ['+JSON.stringify(join(root,'tests/test-setup.ts'))+', "./capture.ts"]\n');
const result=Bun.spawnSync([process.execPath,'test','tests/helpers/test-database.test.ts'],{cwd:work,stdout:'pipe',stderr:'pipe',timeout:45000});
const output=new TextDecoder().decode(result.stdout)+new TextDecoder().decode(result.stderr);
writeFileSync(join(work,'run.txt'),output);
if(result.exitCode!==0)throw Error('Instrumented diagnostic failed; inspect '+work);
const raw=JSON.parse(readFileSync(join(work,'coverage.json'),'utf8'));
const coverage=createCoverageMap(raw);
const files=helperPaths.map(path=>{
 const file=coverage.fileCoverageFor(resolve(path));
 const data=file.data;
 return {path,sourceHash:sourceHash(readFileSync(path,'utf8')),metrics:file.toSummary().data,uncoveredBranches:Object.entries(data.b).flatMap(([id,hits])=>hits.map((count,index)=>({count,index})).filter(x=>x.count===0).map(x=>({id,index:x.index,location:data.branchMap[id]?.locations[x.index],type:data.branchMap[id]?.type}))),uncoveredFunctions:Object.entries(data.f).filter(([,hits])=>hits===0).map(([id])=>data.fnMap[id])};
});
writeFileSync('.git/b11-driver-diagnostic.json',JSON.stringify({scope:'Diagnostic only: direct Istanbul counters retain known B05 optional-chain limitations. No acceptance claimed.',cwd:work,command:[process.execPath,'test','tests/helpers/test-database.test.ts'],exit:result.exitCode,runtime:Bun.version,probeSource:readFileSync('.git/b11-driver-probe.ts','utf8'),files,rawCoverage:raw,sourceInputs:[...helperPaths,'tests/helpers/test-database.test.ts','tests/test-setup.ts'].map(path=>({path,sourceHash:sourceHash(readFileSync(path,'utf8'))})),log:output},null,2)+'\n');
console.log(JSON.stringify({work,files}));

